});

api.get('/ontology', (req, res) => res.json(inference.loadOntology()));

// ---------- 关系推荐（共同邻居 + LLM判断） ----------
api.get('/recommend', (req, res) => {
  const g = db.getGraph();
  const center = String(req.query.center || '').trim();
  const opts = { limit: Number(req.query.limit) || 20 };
  if (center) {
    let cid = null;
    if (/^\d+$/.test(center)) cid = Number(center);
    else {
      const cands = g.entities.filter((e) => e.name === center);
      if (cands.length === 1) cid = cands[0].id;
      else if (cands.length > 1) return res.status(409).json({ error: `实体名"${center}"存在${cands.length}个候选，请改用id`, candidates: cands.map((h) => ({ id: h.id, name: h.name, category: h.category })) });
    }
    if (cid && !g.entities.some((e) => e.id === cid)) return res.status(404).json({ error: `实体"${center}"不存在` });
    if (cid) opts.centerId = cid;
  }
  res.json({ recommendations: recommend.computeCoNeighborRecs(g, opts) });
});

// LLM判断候选关系：只给建议，入库由前端确认后走人工接口
api.post('/recommend/ai', async (req, res) => {
  if (agentBusy) return res.status(429).json({ error: '已有AI任务执行中（问答、导入或智能检索），请稍后再试' });
  const body = req.body || {};
  const g = db.getGraph();
  const byId = new Map(g.entities.map((e) => [e.id, e]));
  const a = byId.get(Number(body.source_id));
  const b = byId.get(Number(body.target_id));
  if (!a || !b) return res.status(404).json({ error: '待判断的实体不存在' });
  agentBusy = true;
  try {
    const judge = await recommend.aiJudgeRelation({ a, b, common_names: body.common_names });
    res.json(judge);
  } catch (e) {
    res.status(e.status || 500).json({ error: e.message });
  } finally {
    agentBusy = false;
  }
});

// ---------- 向量混合检索 ----------
api.get('/embeddings/status', (req, res) => res.json(embeddings.status()));

api.get('/embeddings/settings', (req, res) => {
  const s = embeddings.loadSettings();
  res.json({ ...s, api_key: s.api_key ? '已配置' : '' }); // 不回传真实密钥
});

api.put('/embeddings/settings', (req, res) => {
  try {
    const patch = req.body || {};
    // 前端传"已配置"占位时保留原密钥
    if (patch.api_key === '已配置') delete patch.api_key;
    const s = embeddings.saveSettings(patch);
    res.json({ ...s, api_key: s.api_key ? '已配置' : '' });
  } catch (e) { res.status(400).json({ error: e.message }); }
});

// 测试连接：用当前（或请求体内临时覆盖的）配置向服务方发一次真实embedding请求
api.post('/embeddings/test', async (req, res) => {
  const overrides = req.body || {};
  if (overrides.api_key === '已配置') delete overrides.api_key; // 占位=沿用已存密钥
  const s = { ...embeddings.loadSettings(), ...overrides };
  const started = Date.now();
  try {
    const vec = await embeddings.embed(['连接测试'], s);
    const dim = Array.isArray(vec) && Array.isArray(vec[0]) ? vec[0].length : (vec && vec.length) || 0;
    res.json({ ok: true, model: s.model, base_url: s.base_url, dim, ms: Date.now() - started });
  } catch (e) {
    res.status(400).json({ ok: false, error: e.message, ms: Date.now() - started });
  }
});

api.post('/embeddings/build', async (req, res) => {
  try {
    const result = await embeddings.build();
    res.json(result);
  } catch (e) { res.status(400).json({ error: e.message }); }
});

api.post('/search', async (req, res) => {
  const q = String((req.body || {}).query || '').trim();
  if (!q) return res.status(400).json({ error: 'query不能为空' });
  try {
    res.json(await embeddings.search(q, (req.body || {}).top_k));
  } catch (e) { res.status(400).json({ error: e.message }); }
});

api.post('/cypher', (req, res) => {
  const q = String((req.body || {}).query || '').trim();
  if (!q) return res.status(400).json({ error: 'query不能为空' });
  try { res.json({ rows: db.miniCypher(q) }); }
  catch (e) { res.status(400).json({ error: e.message }); }
});

api.put('/ontology', (req, res) => {
  try { res.json(inference.saveOntology(req.body || {})); }
  catch (e) { res.status(400).json({ error: '本体规则保存失败: ' + e.message }); }
});
api.get('/logs', (req, res) => res.json(db.getLogs(Number(req.query.limit) || 200)));

// ---------- RDF导出 ----------
api.get('/export/rdf', (req, res) => {
