  for (const nd of simNodes) {
    nd.pos.set((Math.random() - 0.5) * 180, (Math.random() - 0.5) * 120, (Math.random() - 0.5) * 180);
    nd.vel.set(0, 0, 0);
  }
  simBudget = 420;
  settleCount = 0;
});
